/**
 * Encryption at rest of the secret settings stored in `app_config` (SECRET_KEYS
 * of config-secrets.ts): a copy of the database alone (dump, backup, volume)
 * no longer gives away the passwords and API keys entered in Settings.
 *
 * AES-256-GCM with CONFIG_ENCRYPTION_KEY from .env (generated by install.sh).
 * The setting name is the additional authenticated data, so an encrypted value
 * cannot be moved to another key. A stored value reads
 *
 *   enc:v1:<key id>:<iv>:<ciphertext>:<tag>      (base64url parts)
 *
 * The key id (first 8 hex characters of the SHA-256 of the key) tells "encrypted
 * with another key" apart from "damaged". A value without the prefix is plain
 * text: stored before the key existed, or on an instance without it. It stays
 * readable, and `provision migrate` encrypts it as soon as the key is set.
 *
 * CONFIG_ENCRYPTION_KEY_PREVIOUS (optional) holds the former key during a
 * rotation: values are read with it and encrypted again with the new key at
 * the next start.
 *
 * No database import here: provision.ts uses this module as well.
 */
import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";

export const ENCRYPTED_PREFIX = "enc:v1:";
export const CONFIG_KEY_ENV = "CONFIG_ENCRYPTION_KEY";
export const CONFIG_PREVIOUS_KEY_ENV = "CONFIG_ENCRYPTION_KEY_PREVIOUS";

const IV_BYTES = 12;
const MIN_PASSPHRASE_LENGTH = 32;

export interface ConfigKey {
  /** First 8 hex characters of the SHA-256 of the key, stored with each value. */
  id: string;
  key: Buffer;
}

/** "active": values are encrypted; "missing": no key, stored in plain text; "invalid": unusable key, same. */
export type ConfigEncryptionStatus = "active" | "missing" | "invalid";

export type DecryptResult =
  | { ok: true; value: string }
  | { ok: false; reason: "no_key" | "other_key" | "damaged" };

/**
 * The key from its .env value: 64 hex characters (what install.sh writes),
 * 32 bytes in base64, or a passphrase of at least 32 characters (hashed).
 * `null` for an empty value; `"invalid"` for a placeholder or a short passphrase.
 */
export function parseConfigKey(raw: string | null | undefined): ConfigKey | null | "invalid" {
  const value = raw?.trim();
  if (!value) return null;
  if (/generate|change-me|your-secret|placeholder/i.test(value)) return "invalid";
  let key: Buffer;
  if (/^[0-9a-fA-F]{64}$/.test(value)) {
    key = Buffer.from(value, "hex");
  } else if (/^[A-Za-z0-9+/]{43}=$/.test(value)) {
    key = Buffer.from(value, "base64");
  } else if (value.length >= MIN_PASSPHRASE_LENGTH) {
    key = createHash("sha256").update(value).digest();
  } else {
    return "invalid";
  }
  return { id: createHash("sha256").update(key).digest("hex").slice(0, 8), key };
}

export function isEncryptedValue(stored: string | null | undefined): boolean {
  return typeof stored === "string" && stored.startsWith(ENCRYPTED_PREFIX);
}

export function encryptSetting(name: string, plain: string, key: ConfigKey): string {
  const iv = randomBytes(IV_BYTES);
  const cipher = createCipheriv("aes-256-gcm", key.key, iv);
  cipher.setAAD(Buffer.from(name, "utf8"));
  const data = Buffer.concat([cipher.update(plain, "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return `${ENCRYPTED_PREFIX}${key.id}:${iv.toString("base64url")}:${data.toString("base64url")}:${tag.toString("base64url")}`;
}

/** Decrypts with whichever of `keys` has the id of the value. A plain value is returned as it is. */
export function decryptSetting(name: string, stored: string, keys: readonly ConfigKey[]): DecryptResult {
  if (!isEncryptedValue(stored)) return { ok: true, value: stored };
  const parts = stored.slice(ENCRYPTED_PREFIX.length).split(":");
  if (parts.length !== 4) return { ok: false, reason: "damaged" };
  const [id, iv, data, tag] = parts;
  if (keys.length === 0) return { ok: false, reason: "no_key" };
  const key = keys.find((k) => k.id === id);
  if (!key) return { ok: false, reason: "other_key" };
  try {
    const decipher = createDecipheriv("aes-256-gcm", key.key, Buffer.from(iv, "base64url"));
    decipher.setAAD(Buffer.from(name, "utf8"));
    decipher.setAuthTag(Buffer.from(tag, "base64url"));
    const value = Buffer.concat([decipher.update(Buffer.from(data, "base64url")), decipher.final()]).toString("utf8");
    return { ok: true, value };
  } catch {
    return { ok: false, reason: "damaged" };
  }
}

/** The id of the key a value was encrypted with, or null for a plain or malformed value. */
export function encryptedKeyId(stored: string): string | null {
  if (!isEncryptedValue(stored)) return null;
  const parts = stored.slice(ENCRYPTED_PREFIX.length).split(":");
  return parts.length === 4 ? parts[0] : null;
}

export interface ConfigKeys {
  status: ConfigEncryptionStatus;
  /** Key used to encrypt, null when the status is not "active". */
  current: ConfigKey | null;
  /** Keys tried to decrypt: the current one, then the previous one. */
  readable: ConfigKey[];
}

let memo: { raw: string; keys: ConfigKeys } | null = null;

/** The keys from the environment, parsed once per value. */
export function loadConfigKeys(env: NodeJS.ProcessEnv = process.env): ConfigKeys {
  const raw = `${env[CONFIG_KEY_ENV] ?? ""}\n${env[CONFIG_PREVIOUS_KEY_ENV] ?? ""}`;
  if (memo?.raw === raw) return memo.keys;
  const current = parseConfigKey(env[CONFIG_KEY_ENV]);
  const previous = parseConfigKey(env[CONFIG_PREVIOUS_KEY_ENV]);
  const usable = (k: ConfigKey | null | "invalid"): k is ConfigKey => k !== null && k !== "invalid";
  const keys: ConfigKeys = {
    status: current === null ? "missing" : current === "invalid" ? "invalid" : "active",
    current: usable(current) ? current : null,
    readable: [current, previous].filter(usable),
  };
  memo = { raw, keys };
  return keys;
}
